const j = $input.first().json;
let workflowName = 'نامشخص', nodeName = 'نامشخص', message = 'خطای نامشخص';
try { workflowName = (j.workflow && j.workflow.name) || workflowName; } catch (e) {}
try { nodeName = (j.execution && j.execution.lastNodeExecuted) || nodeName; } catch (e) {}
try { message = (j.execution && j.execution.error && j.execution.error.message) || message; } catch (e) {}
return [{ json: { workflowName: workflowName, nodeName: nodeName, message: String(message).slice(0, 500) } }];
